import os
from typing import Any, Dict, List, Optional

from google.cloud import documentai_v1 as documentai


def _get_text(
    text_anchor: documentai.Document.TextAnchor,
    full_text: str,
) -> str:
    if not text_anchor.text_segments:
        return ""
    parts: List[str] = []
    for segment in text_anchor.text_segments:
        start = int(segment.start_index or 0)
        end = int(segment.end_index or 0)
        parts.append(full_text[start:end])
    return "".join(parts).strip()


def extract_key_value_pairs(
    file_path: str,
    project_id: str,
    location: str,
    processor_id: str,
    mime_type: Optional[str] = None,
) -> Dict[str, Any]:
    if mime_type is None:
        ext = os.path.splitext(file_path)[1].lower()
        if ext == ".pdf":
            mime_type = "application/pdf"
        elif ext in {".jpg", ".jpeg"}:
            mime_type = "image/jpeg"
        elif ext == ".png":
            mime_type = "image/png"
        elif ext == ".tif" or ext == ".tiff":
            mime_type = "image/tiff"
        else:
            raise ValueError("Unsupported file type; provide mime_type explicitly.")

    client = documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{location}-documentai.googleapis.com"}
    )

    name = client.processor_path(project_id, location, processor_id)

    with open(file_path, "rb") as f:
        raw_document = documentai.RawDocument(content=f.read(), mime_type=mime_type)

    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    result = client.process_document(request=request)
    document = result.document

    key_value_pairs: List[Dict[str, Any]] = []

    for page in document.pages:
        for form_field in page.form_fields:
            key_text = _get_text(form_field.field_name.text_anchor, document.text)
            value_text = _get_text(form_field.field_value.text_anchor, document.text)

            item: Dict[str, Any] = {
                "key": key_text,
                "value": value_text,
            }

            if form_field.field_name.bounding_poly and form_field.field_name.bounding_poly.normalized_vertices:
                item["key_bbox"] = [
                    {"x": v.x, "y": v.y}
                    for v in form_field.field_name.bounding_poly.normalized_vertices
                ]

            if form_field.field_value.bounding_poly and form_field.field_value.bounding_poly.normalized_vertices:
                item["value_bbox"] = [
                    {"x": v.x, "y": v.y}
                    for v in form_field.field_value.bounding_poly.normalized_vertices
                ]

            key_value_pairs.append(item)

    return {
        "provider": "google-cloud-documentai",
        "processor": name,
        "text": document.text,
        "key_value_pairs": key_value_pairs,
    }
